s/site/sections.tsx:29:5"><div class="container-page" data-tsd-source="/src/components/site/sections.tsx:38:7"><div class="grid gap-12 lg:grid-cols-[minmax(0,1fr)_18rem] lg:items-start" data-tsd-source="/src/components/site/PageTemplate.tsx:106:9"><div data-tsd-source="/src/components/site/PageTemplate.tsx:107:11"><div class="space-y-14" data-tsd-source="/src/components/site/sections.tsx:252:5"><section id="key-takeaways" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">Key Takeaways</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><div data-tsd-source="/src/components/site/sections.tsx:132:13"><ul class="space-y-2" data-tsd-source="/src/components/site/sections.tsx:134:15"><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Expert strategies tailored for AI Agent Development Services</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Data-driven approach without relying on guesswork</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Focus on sustainable, long-term search visibility</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Fully aligned with modern Answer Engine and AI search requirements</span></li></ul></div></div></section><section id="what-is-an-ai-agent" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">What is an AI agent?</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><p class="text-balance-pretty text-base leading-relaxed text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:125:13">An AI agent is a software system designed to interpret a task, use available tools or information, make decisions within defined boundaries and execute actions according to its configuration. In practice that means it can read a request, look up what it needs, choose from a limited set of permitted actions and report back.</p><p class="text-balance-pretty text-base leading-relaxed text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:125:13">The useful ones are narrow. An agent with a clear job, a clear set of tools and clear limits is far more dependable than one asked to handle anything.</p></div></section><section id="what-we-build" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">What we can build</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><div data-tsd-source="/src/components/site/sections.tsx:132:13"><ul class="space-y-2" data-tsd-source="/src/components/site/sections.tsx:134:15"><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Customer support assistants that answer from your own approved content</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Lead qualification agents that ask defined questions and route enquiries</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Internal knowledge assistants for policies, documentation and process questions</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Data-processing agents that summarise, classify or extract structured information</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Workflow agents that trigger and follow up on connected processes</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Research assistants that gather and organise information for review</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Business task assistants for repetitive, well-defined internal requests</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">AI-powered workflow systems that combine an agent with automation steps</span></li></ul></div></div></section><section id="agent-workflow" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">How an AI agent works</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><div data-tsd-source="/src/components/site/sections.tsx:150:13"><ol class="space-y-4" data-tsd-source="/src/components/site/sections.tsx:152:15"><li class="flex gap-4" data-tsd-source="/src/components/site/sections.tsx:154:19"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary font-display text-sm font-bold text-primary-foreground" data-tsd-source="/src/components/site/sections.tsx:155:21">1</span><span data-tsd-source="/src/components/site/sections.tsx:158:21"><span class="block font-semibold" data-tsd-source="/src/components/site/sections.tsx:159:23">User / trigger</span><span class="block text-foreground/80" data-tsd-source="/src/components/site/sections.tsx:160:23">A person asks something, or an event in a connected system starts the agent.</span></span></li><li class="flex gap-4" data-tsd-source="/src/components/site/sections.tsx:154:19"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary font-display text-sm font-bold text-primary-foreground" data-tsd-source="/src/components/site/sections.tsx:155:21">2</span><span data-tsd-source="/src/components/site/sections.tsx:158:21"><span class="block font-semibold" data-tsd-source="/src/components/site/sections.tsx:159:23">Understand task</span><span class="block text-foreground/80" data-tsd-source="/src/components/site/sections.tsx:160:23">The agent interprets the request against its instructions and boundaries.</span></span></li><li class="flex gap-4" data-tsd-source="/src/components/site/sections.tsx:154:19"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary font-display text-sm font-bold text-primary-foreground" data-tsd-source="/src/components/site/sections.tsx:155:21">3</span><span data-tsd-source="/src/components/site/sections.tsx:158:21"><span class="block font-semibold" data-tsd-source="/src/components/site/sections.tsx:159:23">Retrieve information</span><span class="block text-foreground/80" data-tsd-source="/src/components/site/sections.tsx:160:23">It looks up the documents, records or data it has been given access to.</span></span></li><li class="flex gap-4" data-tsd-source="/src/components/site/sections.tsx:154:19"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary font-display text-sm font-bold text-primary-foreground" data-tsd-source="/src/components/site/sections.tsx:155:21">4</span><span data-tsd-source="/src/components/site/sections.tsx:158:21"><span class="block font-semibold" data-tsd-source="/src/components/site/sections.tsx:159:23">Use tools</span><span class="block text-foreground/80" data-tsd-source="/src/components/site/sections.tsx:160:23">It calls the specific tools or APIs it is permitted to use.</span></span></li><li class="flex gap-4" data-tsd-source="/src/components/site/sections.tsx:154:19"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary font-display text-sm font-bold text-primary-foreground" data-tsd-source="/src/components/site/sections.tsx:155:21">5</span><span data-tsd-source="/src/components/site/sections.tsx:158:21"><span class="block font-semibold" data-tsd-source="/src/components/site/sections.tsx:159:23">Perform action</span><span class="block text-foreground/80" data-tsd-source="/src/components/site/sections.tsx:160:23">It carries out the allowed action, or requests human approval when required.</span></span></li><li class="flex gap-4" data-tsd-source="/src/components/site/sections.tsx:154:19"><span class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary font-display text-sm font-bold text-primary-foreground" data-tsd-source="/src/components/site/sections.tsx:155:21">6</span><span data-tsd-source="/src/components/site/sections.tsx:158:21"><span class="block font-semibold" data-tsd-source="/src/components/site/sections.tsx:159:23">Return result</span><span class="block text-foreground/80" data-tsd-source="/src/components/site/sections.tsx:160:23">It returns an answer or outcome, and the interaction is logged.</span></span></li></ol></div></div></section><section id="agents-and-automation" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">AI agents with automation</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><p class="text-balance-pretty text-base leading-relaxed text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:125:13">Agents and workflow automation solve different halves of the same problem. The agent handles interpretation and decision-making; the automation platform reliably carries out the steps. Conceptually the pattern looks like this:</p><div data-tsd-source="/src/components/site/sections.tsx:132:13"><ul class="space-y-2" data-tsd-source="/src/components/site/sections.tsx:134:15"><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">User request arrives through a form, chat or connected application</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">The AI agent interprets the request and gathers what it needs</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">A decision is made within the boundaries the agent has been given</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">An n8n workflow executes the resulting steps</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">External applications are updated through their APIs</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">The result is returned to the user and recorded</span></li></ul></div><div class="rounded-xl border-l-4 border-amber bg-amber/10 p-5" data-tsd-source="/src/components/site/sections.tsx:240:11"><p class="font-display font-semibold" data-tsd-source="/src/components/site/sections.tsx:241:13">Designed per use case</p><p class="mt-1 text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:242:13">This is a conceptual pattern. The actual design depends on your tools, data and how much autonomy is appropriate.</p></div></div></section><section id="benefits" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">Benefits</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><div data-tsd-source="/src/components/site/sections.tsx:132:13"><ul class="space-y-2" data-tsd-source="/src/components/site/sections.tsx:134:15"><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Automate repetitive tasks that still need some interpretation</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Assist employees by handling first-line questions and lookups</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Process information such as long documents, forms or enquiry text</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Connect business workflows that currently require manual coordination</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Improve operational efficiency on high-volume, low-complexity requests</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Create digital assistants scoped to your own content and systems</span></li></ul></div></div></section><section id="limitations" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">Limitations you should know about</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><p class="text-balance-pretty text-base leading-relaxed text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:125:13">AI agents are not autonomous and they are not error-free. We would rather set expectations correctly than sell an idea that fails in production.</p><div data-tsd-source="/src/components/site/sections.tsx:132:13"><ul class="space-y-2" data-tsd-source="/src/components/site/sections.tsx:134:15"><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">They can make incorrect decisions, particularly on unusual inputs</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">They can misunderstand instructions that are ambiguous or incomplete</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">They can produce incorrect information stated confidently</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">They require monitoring of what they answer and what they do</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">They require access controls, so an agent can only touch what it should</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">They require testing against real cases before being trusted</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">They require human oversight for decisions that carry cost or risk</span></li></ul></div></div></section><section id="security" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:254:9"><h2 class="mb-5 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:255:11">Security and reliability</h2><div class="space-y-6" data-tsd-source="/src/components/site/sections.tsx:121:5"><div data-tsd-source="/src/components/site/sections.tsx:132:13"><ul class="space-y-2" data-tsd-source="/src/components/site/sections.tsx:134:15"><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Access control and least-privilege permissions for every tool an agent can use</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Authentication for the interfaces through which the agent is reached</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Data protection rules covering what the agent may read, store and send</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Logging of requests, decisions and actions for review</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Monitoring so unexpected behaviour is noticed early</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Error handling and safe fallbacks when a step fails</span></li><li class="flex gap-3" data-tsd-source="/src/components/site/sections.tsx:136:19"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check mt-1 h-4 w-4 shrink-0 text-primary" aria-hidden="true" data-tsd-source="/src/components/site/sections.tsx:137:21"><path d="M20 6 9 17l-5-5"></path></svg><span class="text-foreground/90" data-tsd-source="/src/components/site/sections.tsx:141:21">Human approval steps before actions that are costly or hard to reverse</span></li></ul></div></div></section></div><div class="mt-14" data-tsd-source="/src/components/site/PageTemplate.tsx:136:13"><div id="faqs" class="scroll-mt-28" data-tsd-source="/src/components/site/sections.tsx:289:5"><h2 class="mb-6 text-2xl font-bold lg:text-3xl" data-tsd-source="/src/components/site/sections.tsx:290:7">Frequently asked questions</h2><div class="rounded-2xl border border-border bg-card px-5" data-tsd-source="/src/components/site/sections.tsx:293:7" data-orientation="vertical"><div data-state="closed" data-orientation="vertical" class="border-b" data-tsd-source="/src/components/site/sections.tsx:295:11"><h3 data-orientation="vertical" data-state="closed" class="flex" data-tsd-source="/src/components/ui/accordion.tsx:21:3"><button type="button" aria-expanded="false" data-state="closed" data-orientation="vertical" id="